////////////////////////////////////////////////////////////////////////////////
/// RSDD (https://github.com/neuppl/rsdd) is used through the C interface of its
/// crate (`src/ffi`, feature `ffi`), which exports BCDDs over one builder, the
/// `RobddBuilder` with the apply cache `AllIteTable`. That cache is a hash map
/// from ITE triples in standard form to their results which is never evicted or
/// cleared, so it keeps every ITE computed by every operation. RSDD's own CNF
/// compiler `bottomup_cnf_to_bdd` uses the bounded `LruIteTable` instead, which
/// the interface does not export. The nodes live in an arena that only grows:
/// there is no garbage collection and no node limit, so `-M` has no effect and
/// a build that exhausts the memory is ended from outside.
///
/// Every BDD crosses the interface as a pointer to a heap box holding RSDD's
/// `BddPtr`, allocated by each call that returns a BDD, and the interface has no
/// function to free it. These boxes cannot be freed, so every such call leaks
/// one box. The adapter makes one call per operation where the interface
/// allows: the constants and the literals are boxed once and shared, copies of
/// a BDD share its box, and `apply_imp`, `apply_diff` and `ite` are single ITEs.
/// The interface has no exclusive or, so `apply_xor` and `apply_xnor` take two
/// calls, a negation and an ITE. The builder, the variable order it takes
/// over, and the weights of the counts are freed.
///
/// The interface has no quantification and no cofactor, but it has the
/// composition `bdd_compose(f, x, g)`, which RSDD computes as the existential
/// quantification of `x` from `(x <-> g) & f`. With `g` the positive literal of
/// `x` the biconditional is true, so `bdd_compose(f, x, x)` is the existential
/// quantification of `x` from `f`, one call per variable. With `g` a function
/// that does not depend on `x` it is the substitution of `g` for `x`, which
/// renames the variables of the relational products one at a time.
///
/// The interface has no traversal of its own, but it exports the variable and
/// the two children of the root of a BDD, `bdd_topvar`, `bdd_low` and
/// `bdd_high`, where the children are those of the function the pointer
/// denotes, with the complement of a complemented pointer applied to them. It
/// also exports a field of each node for the traversals of RSDD, its scratch,
/// which a traversal here sets on every node it visits and clears from the root
/// afterwards, as RSDD's own traversals do. Each child taken leaks one box.
///
/// The counts are `bdd_wmc`, a sum over the paths to true of the products of
/// the weights of the literals on each path, computed in `f64`. A variable that
/// a path does not test contributes the factor one to it, rather than the sum
/// of its two weights, so this is the weighted model count only if every
/// variable that a path to true skips has weights that sum to one. The model
/// count therefore takes the weights one half for every variable, which yields
/// the fraction of the assignments that satisfy the BDD, and scales it by
/// `2^n` exactly. The interface has no count of the nodes stored by the
/// builder, so the adapter cannot report the allocated nodes, and it has no
/// export of a BDD to a file.
////////////////////////////////////////////////////////////////////////////////

namespace rsdd
{
  /// Number of boxes the interface has allocated for BDDs, none of which is freed
  inline uint64_t boxes = 0;

  /// Take a box returned by the interface
  inline BddPtr*
  boxed(BddPtr* ptr) noexcept
  {
    ++boxes;
    return ptr;
  }

  /// A statistic that the interface cannot provide, printed as the JSON value `null`
  struct not_available
  {};

  inline std::ostream&
  operator<<(std::ostream& os, const not_available&)
  {
    return os << "null";
  }

  /// \brief A BDD of RSDD, the builder together with the box holding the root.
  ///
  /// The box cannot be freed, so copies share it and destruction leaves it.
  class bdd_function
  {
    RsddBddBuilder* _builder = nullptr;
    BddPtr* _ptr             = nullptr;

  public:
    bdd_function() noexcept = default;

    bdd_function(RsddBddBuilder* builder, BddPtr* ptr) noexcept
      : _builder(builder)
      , _ptr(ptr)
    {}

    BddPtr*
    get() const noexcept
    {
      return _ptr;
    }

    bool
    is_invalid() const noexcept
    {
      return _ptr == nullptr;
    }

    bool
    operator==(const bdd_function& rhs) const noexcept
    {
      if (_ptr == nullptr || rhs._ptr == nullptr) { return _ptr == rhs._ptr; }
      return _ptr == rhs._ptr || bdd_eq(_builder, _ptr, rhs._ptr);
    }

    bool
    operator!=(const bdd_function& rhs) const noexcept
    {
      return !(*this == rhs);
    }

    bdd_function
    operator~() const noexcept
    {
      return { _builder, boxed(bdd_negate(_builder, _ptr)) };
    }

    bdd_function
    operator&(const bdd_function& rhs) const noexcept
    {
      return { _builder, boxed(bdd_and(_builder, _ptr, rhs._ptr)) };
    }

    bdd_function&
    operator&=(const bdd_function& rhs) noexcept
    {
      return (*this = *this & rhs);
    }

    bdd_function
    operator|(const bdd_function& rhs) const noexcept
    {
      return { _builder, boxed(bdd_or(_builder, _ptr, rhs._ptr)) };
    }

    bdd_function&
    operator|=(const bdd_function& rhs) noexcept
    {
      return (*this = *this | rhs);
    }

    /// `this ∧ ¬rhs`, as a negation and a conjunction, since a single ITE would need a box of
    /// false
    bdd_function
    operator-(const bdd_function& rhs) const noexcept
    {
      return *this & ~rhs;
    }

    bdd_function&
    operator-=(const bdd_function& rhs) noexcept
    {
      return (*this = *this - rhs);
    }

    /// `ite(this, t, e)`
    bdd_function
    ite(const bdd_function& t, const bdd_function& e) const noexcept
    {
      return { _builder, boxed(bdd_ite(_builder, _ptr, t._ptr, e._ptr)) };
    }

    bdd_function
    operator^(const bdd_function& rhs) const noexcept
    {
      return ite(~rhs, rhs);
    }

    bdd_function&
    operator^=(const bdd_function& rhs) noexcept
    {
      return (*this = *this ^ rhs);
    }

    /// The composition `bdd_compose(this, label, g)`, the existential quantification of `label`
    /// from `(label <-> g) & this`
    bdd_function
    compose(const uint32_t label, const bdd_function& g) const noexcept
    {
      return { _builder, boxed(bdd_compose(_builder, _ptr, label, g._ptr)) };
    }

    bool
    is_true() const noexcept
    {
      return bdd_is_true(_ptr);
    }

    bool
    is_false() const noexcept
    {
      return bdd_is_false(_ptr);
    }

    bool
    is_const() const noexcept
    {
      return bdd_is_const(_ptr);
    }

    /// Variable of the root, which must not be constant
    uint32_t
    topvar() const noexcept
    {
      return bdd_topvar(_ptr);
    }

    /// Low child of the function, whose root must not be constant
    bdd_function
    low() const noexcept
    {
      return { _builder, boxed(bdd_low(_ptr)) };
    }

    /// High child of the function, whose root must not be constant
    bdd_function
    high() const noexcept
    {
      return { _builder, boxed(bdd_high(_ptr)) };
    }
  };
}

class rsdd_bcdd_adapter
{
public:
  static constexpr std::string_view name = "RSDD";
  static constexpr std::string_view dd   = "BCDD";

  static constexpr bool needs_extend     = false;
  static constexpr bool needs_frame_rule = true;

  static constexpr bool complement_edges = true;

  using dd_t         = rsdd::bdd_function;
  using build_node_t = rsdd::bdd_function;

private:
  const uint32_t _varcount;

  RsddBddBuilder* _builder;

  dd_t _top;
  dd_t _bot;

  /// The positive and the negative literal of each variable
  std::vector<dd_t> _ithvar;
  std::vector<dd_t> _nithvar;

  /// Weights one half for every variable, built by the first model count
  WmcParams_RealSemiring* _halves = nullptr;

  dd_t _latest_build;

  /// A builder over the variables `order`, from the top to the bottom
  static RsddBddBuilder*
  make_builder(const std::vector<uint64_t>& order)
  {
    // The builder takes over the order
    return robdd_builder_all_table(var_order_new(order.data(), order.size()));
  }

  static std::vector<uint64_t>
  identity_order(const uint32_t varcount)
  {
    std::vector<uint64_t> order(varcount);
    std::iota(order.begin(), order.end(), 0);
    return order;
  }

  // Init and Deinit
public:
  /// A builder over the variables `0` to `varcount - 1` in this order
  rsdd_bcdd_adapter(const uint32_t varcount)
    : rsdd_bcdd_adapter(identity_order(varcount))
  {}

  /// A builder over the variables `0` to `order.size() - 1` in the order `order`, from the top
  /// to the bottom
  rsdd_bcdd_adapter(const std::vector<uint64_t>& order)
    : _varcount(order.size())
    , _builder(make_builder(order))
  {
    _top = dd_t(_builder, rsdd::boxed(bdd_true(_builder)));
    _bot = dd_t(_builder, rsdd::boxed(bdd_false(_builder)));

    _ithvar.reserve(_varcount);
    _nithvar.reserve(_varcount);
    for (uint64_t x = 0; x < _varcount; ++x) {
      _ithvar.emplace_back(_builder, rsdd::boxed(bdd_var(_builder, x, true)));
      _nithvar.emplace_back(_builder, rsdd::boxed(bdd_var(_builder, x, false)));
    }
  }

  rsdd_bcdd_adapter(const rsdd_bcdd_adapter&) = delete;

  rsdd_bcdd_adapter&
  operator=(const rsdd_bcdd_adapter&) = delete;

  ~rsdd_bcdd_adapter()
  {
    if (_halves) { free_wmc_params_f64(_halves); }
    free_bdd_manager(_builder);
  }

  template <typename F>
  int
  run(const F& f)
  {
    return f();
  }

  // BDD Operations
public:
  inline dd_t
  top()
  {
    return _top;
  }

  inline dd_t
  bot()
  {
    return _bot;
  }

  inline dd_t
  ithvar(const uint32_t label)
  {
    return _ithvar.at(label);
  }

  inline dd_t
  nithvar(const uint32_t label)
  {
    return _nithvar.at(label);
  }

  /// Conjunction of the positive literals of the variables from `rbegin` to `rend`, built from
  /// the last one with one ITE per variable
  template <typename IT>
  inline dd_t
  cube(IT rbegin, IT rend)
  {
    dd_t res = _top;
    while (rbegin != rend) { res = ithvar(*(rbegin++)).ite(res, _bot); }
    return res;
  }

  /// Conjunction of the positive literals of the variables that satisfy `pred`, with one ITE per
  /// variable
  inline dd_t
  cube(const std::function<bool(int)>& pred)
  {
    dd_t res = _top;
    for (int x = _varcount - 1; 0 <= x; --x) {
      if (pred(x)) { res = ithvar(x).ite(res, _bot); }
    }
    return res;
  }

  inline dd_t
  apply_and(const dd_t& f, const dd_t& g)
  {
    return f & g;
  }

  inline dd_t
  apply_or(const dd_t& f, const dd_t& g)
  {
    return f | g;
  }

  /// `f ∧ ¬g`, as `ite(g, ⊥, f)`
  inline dd_t
  apply_diff(const dd_t& f, const dd_t& g)
  {
    return g.ite(_bot, f);
  }

  /// `f → g`, as `ite(f, g, ⊤)`
  inline dd_t
  apply_imp(const dd_t& f, const dd_t& g)
  {
    return f.ite(g, _top);
  }

  inline dd_t
  apply_xor(const dd_t& f, const dd_t& g)
  {
    return f ^ g;
  }

  /// `f ↔ g`, as `ite(f, g, ¬g)`
  inline dd_t
  apply_xnor(const dd_t& f, const dd_t& g)
  {
    return f.ite(g, ~g);
  }

  inline dd_t
  ite(const dd_t& i, const dd_t& t, const dd_t& e)
  {
    return i.ite(t, e);
  }

  template <typename IT>
  inline dd_t
  extend(const dd_t& f, IT /*begin*/, IT /*end*/)
  {
    return f;
  }

  /// Existential quantification of `x` from `f`, as the single call `bdd_compose(f, x, x)` (see
  /// the comment at the top), which conditions `f` on both values of `x` and takes the
  /// disjunction. It leaks one box, and it traverses `f` even if `x` is not in its support.
  inline dd_t
  exists(const dd_t& f, const int x)
  {
    return f.compose(x, ithvar(x));
  }

  /// Existential quantification of the variables that satisfy `pred`, one composition and one
  /// leaked box per variable from the last one, which stops once the result is constant
  inline dd_t
  exists(dd_t f, const std::function<bool(int)>& pred)
  {
    for (int x = _varcount - 1; 0 <= x && !f.is_const(); --x) {
      if (pred(x)) { f = exists(f, x); }
    }
    return f;
  }

  /// Existential quantification of the variables from `rbegin` to `rend`, one composition and
  /// one leaked box per variable, which stops once the result is constant
  template <typename IT>
  inline dd_t
  exists(dd_t f, IT rbegin, IT rend)
  {
    for (; rbegin != rend && !f.is_const(); ++rbegin) { f = exists(f, *rbegin); }
    return f;
  }

  /// Universal quantification of `x` from `f`, as the negation of the existential quantification
  /// of `x` from the negation of `f`, which adds two calls and two leaked boxes
  inline dd_t
  forall(const dd_t& f, const int x)
  {
    return ~exists(~f, x);
  }

  inline dd_t
  forall(const dd_t& f, const std::function<bool(int)>& pred)
  {
    return ~exists(~f, pred);
  }

  template <typename IT>
  inline dd_t
  forall(const dd_t& f, IT rbegin, IT rend)
  {
    return ~exists(~f, rbegin, rend);
  }

  /// Relational product of `states` and `rel` followed by the renaming of the next-state
  /// variables `2i+1` to the current-state variables `2i`, as in the CUDD adapter, whose
  /// quantification and renaming cover all variables regardless of `rel_support`.
  ///
  /// The conjunction is quantified over the current-state variables of its support and then
  /// renamed by substituting `2i` for each `2i+1` of the support of the result. No current-state
  /// variable is left, and no substituted variable is renamed again, so the substitutions one at
  /// a time are the simultaneous one. The supports are taken by two traversals, since a
  /// composition over a variable outside the support still conjoins the biconditional with the
  /// function and stores the nodes of that conjunction for good.
  inline dd_t
  relnext(const dd_t& states, const dd_t& rel, const dd_t& /*rel_support*/)
  {
    dd_t res = states & rel;
    for (const uint32_t x : support(res)) {
      if (x % 2 == 0) { res = exists(res, x); }
    }
    for (const uint32_t x : support(res)) {
      if (x % 2 == 1) { res = res.compose(x, ithvar(x & ~1u)); }
    }
    return res;
  }

  /// Renaming of the current-state variables `2i` of `states` to the next-state variables
  /// `2i+1` followed by the relational product with `rel` over the next-state variables, as in
  /// the CUDD adapter, whose renaming and quantification cover all variables regardless of
  /// `rel_support`.
  ///
  /// The renaming substitutes `2i+1` for each `2i` of the support of `states`. No substituted
  /// variable is renamed again, so the substitutions one at a time are the simultaneous one. The
  /// conjunction is then quantified over the next-state variables of its support. The supports
  /// are taken by two traversals, as in `relnext`.
  inline dd_t
  relprev(const dd_t& states, const dd_t& rel, const dd_t& /*rel_support*/)
  {
    dd_t res = states;
    for (const uint32_t x : support(states)) {
      if (x % 2 == 0) { res = res.compose(x, ithvar(x | 1u)); }
    }
    res &= rel;
    for (const uint32_t x : support(res)) {
      if (x % 2 == 1) { res = exists(res, x); }
    }
    return res;
  }

  /// Number of nodes of `f`. RSDD counts the inner nodes; the terminal is added, as in the
  /// counts of the other packages.
  inline uint64_t
  nodecount(const dd_t& f)
  {
    return bdd_count_nodes(f.get()) + 1;
  }

  /// Number of satisfying assignments of `f` over all variables
  inline uint64_t
  satcount(const dd_t& f)
  {
    return satcount(f, _varcount);
  }

  /// Number of satisfying assignments of `f` over `vc` variables, which must include its support
  ///
  /// With the weights one half for every variable, `bdd_wmc` sums `2^-k` over the paths to
  /// true, `k` the number of variables on the path, which is the fraction of the assignments
  /// that satisfy `f`; scaling by `2^vc` is exact. Every term is at least `2^-n`, `n` the number
  /// of variables, so no value is subnormal if `n` is at most 1022.
  inline uint64_t
  satcount(const dd_t& f, const size_t vc)
  {
    if (_varcount > 1022) {
      throw std::range_error("RSDD counts the fraction of the assignments in f64, which loses "
                             "precision beyond 1022 variables");
    }
    if (!_halves) {
      _halves = new_wmc_params_f64();
      for (uint64_t x = 0; x < _varcount; ++x) wmc_param_f64_set_weight(_halves, x, 0.5, 0.5);
    }
    return checked_satcount(std::ldexp(bdd_wmc(f.get(), _halves), vc));
  }

  /// The count `bdd_wmc` of `f` with the weights `weights[x] = (low, high)` of the literals
  /// `¬x` and `x` of each variable `x`, indexed as `ithvar`.
  ///
  /// This is the sum over the paths to true of the products of the weights of the literals on
  /// each path, which is the weighted model count of `f` if every variable that a path to true
  /// skips has weights that sum to one (see the comment at the top). It is the count of the
  /// CNF benchmark's weighted model counting (`-q`).
  inline double
  wmc(const dd_t& f, const std::vector<std::pair<double, double>>& weights)
  {
    if (weights.size() != _varcount) {
      throw std::invalid_argument("expected one pair of weights per variable");
    }
    WmcParams_RealSemiring* params = new_wmc_params_f64();
    for (uint64_t x = 0; x < _varcount; ++x) {
      wmc_param_f64_set_weight(params, x, weights[x].first, weights[x].second);
    }
    const double result = bdd_wmc(f.get(), params);
    free_wmc_params_f64(params);
    return result;
  }

  /// A satisfying assignment of `f` to the variables of its support, as their conjunction
  inline dd_t
  satone(const dd_t& f)
  {
    return satone(f, f);
  }

  /// A satisfying assignment of `f` to the variables of the support of `c`, as their
  /// conjunction, or `⊥` if `f` is unsatisfiable
  ///
  /// The variables are those of `pickcube(f)` with its values, and the value false for the
  /// variables of `c` that the path does not test; the variables of the path outside the support
  /// of `c` are left out, as in CUDD's `Cudd_bddPickOneMinterm`. The conjunction takes one ITE
  /// per variable.
  inline dd_t
  satone(const dd_t& f, const dd_t& c)
  {
    if (f.is_false()) { return _bot; }

    std::vector<char> value(_varcount, '0');
    for (const auto& [x, v] : pickcube(f)) { value.at(x) = v; }

    const std::vector<uint32_t> vars = support(c);
    dd_t res                         = _top;
    for (auto x = vars.rbegin(); x != vars.rend(); ++x) {
      res = value.at(*x) == '1' ? ithvar(*x).ite(res, _bot) : ithvar(*x).ite(_bot, res);
    }
    return res;
  }

  /// The literals of a path from the root of `f` to true, in the order of the path, which takes
  /// the low child unless it is false. The path is empty if `f` is constant.
  inline std::vector<std::pair<int, char>>
  pickcube(const dd_t& f)
  {
    std::vector<std::pair<int, char>> res;
    if (f.is_false()) { return res; }

    dd_t node = f;
    while (!node.is_const()) {
      const dd_t low = node.low();
      const bool go_high = low.is_false();
      res.push_back({ static_cast<int>(node.topvar()), '0' + go_high });
      node = go_high ? node.high() : low;
    }
    return res;
  }

  /// Writes `f` in the DOT format to `filename`.
  ///
  /// Each node of RSDD is drawn once, labelled with its variable, and stands for the function of
  /// the first pointer to it that the traversal meets. An edge to it from a pointer to its
  /// complement ends in a circle; the low edges are dashed. Since RSDD has two terminals, which
  /// are not complements of each other, the edges into them are never complemented.
  void
  print_dot(const dd_t& f, const std::string& filename)
  {
    std::ofstream out(filename);
    out << "digraph BDD {" << std::endl
        << "  f [shape=none, label=\"\"];" << std::endl
        << "  t0 [shape=box, label=\"0\"];" << std::endl
        << "  t1 [shape=box, label=\"1\"];" << std::endl;

    // The pointer that each node stands for, at the scratch of the node minus one
    std::vector<dd_t> nodes;

    // Writes the end of an edge into the node of `g` with the attributes `attrs`
    const auto edge = [&](const dd_t& g, std::string attrs) {
      if (g.is_const()) {
        out << (g.is_true() ? "t1" : "t0");
      } else {
        size_t id = bdd_scratch(g.get(), 0);
        if (id == 0) {
          nodes.push_back(g);
          id = nodes.size();
          bdd_set_scratch(g.get(), id);
        }
        out << "n" << (id - 1);
        if (g != nodes.at(id - 1)) {
          attrs += (attrs.empty() ? "" : ", ") + std::string("arrowhead=odot");
        }
      }
      if (!attrs.empty()) { out << " [" << attrs << "]"; }
      out << ";" << std::endl;
    };

    out << "  f -> ";
    edge(f, "");
    for (size_t i = 0; i < nodes.size(); ++i) {
      const dd_t node = nodes.at(i);
      out << "  n" << i << " [label=\"x" << node.topvar() << "\"];" << std::endl;
      out << "  n" << i << " -> ";
      edge(node.low(), "style=dashed");
      out << "  n" << i << " -> ";
      edge(node.high(), "");
    }
    out << "}" << std::endl;

    if (!f.is_const()) { bdd_clear_scratch(f.get()); }
  }

  void
  save(const dd_t&, const std::string&)
  {
    std::cerr << "'rsdd_bcdd_adapter' does not support BCDD export" << std::endl;
  }

  // BDD Build Operations
public:
  inline dd_t
  build_node(const bool value)
  {
    const dd_t res = value ? _top : _bot;
    if (_latest_build.is_invalid() || _latest_build == _top || _latest_build == _bot) {
      _latest_build = res;
    }
    return res;
  }

  inline dd_t
  build_node(const uint32_t label, const dd_t& low, const dd_t& high)
  {
    return _latest_build = _ithvar.at(label).ite(high, low);
  }

  inline dd_t
  build()
  {
    dd_t res      = _latest_build;
    _latest_build = dd_t();
    return res;
  }

  // Statistics
public:
#ifndef BDD_BENCHMARK_STATS
  /// Not supported by the interface, which has no count of the nodes stored by the builder. The
  /// picotrav benchmark prints it as `null`.
  inline rsdd::not_available
  allocated_nodes()
  {
    return {};
  }
#else
  /// Not supported by the interface, which has no count of the nodes stored by the builder. The
  /// statistics of the picotrav benchmark take it as a number, so it throws there.
  inline size_t
  allocated_nodes()
  {
    throw std::logic_error("The C interface of RSDD has no count of the allocated nodes");
  }
#endif

  void
  print_stats()
  {
    std::cout << "RSDD statistics:" << std::endl
              << "  recursive calls: " << bdd_num_recursive_calls(_builder) << std::endl
              << "  boxes of BDDs (never freed): " << rsdd::boxes << std::endl;
  }

private:
  /// The variables of the support of `f` in ascending order, by a traversal that marks each
  /// node in its scratch and leaks the boxes of the two children of each node
  inline std::vector<uint32_t>
  support(const dd_t& f)
  {
    std::vector<bool> in_support(_varcount, false);
    if (!f.is_const()) {
      std::vector<dd_t> stack = { f };
      while (!stack.empty()) {
        const dd_t node = stack.back();
        stack.pop_back();
        if (node.is_const() || bdd_scratch(node.get(), 0) != 0) { continue; }

        bdd_set_scratch(node.get(), 1);
        in_support.at(node.topvar()) = true;
        stack.push_back(node.low());
        stack.push_back(node.high());
      }
      bdd_clear_scratch(f.get());
    }

    std::vector<uint32_t> res;
    for (uint32_t x = 0; x < _varcount; ++x) {
      if (in_support[x]) { res.push_back(x); }
    }
    return res;
  }
};
